// ── Fractal noise library (inlined, O(n) scanline) ──────────────────────
    // Multi-scale procedural extrapolation fills empty southern-hemisphere pixels
    // using fractal noise seeded from nearest real pixel and northern palette.
    // Matches New Horizons statistics: mean altitude -1.6km, RMS roughness 0.72km.
    function fade(t){return t*t*t*(t*(t*6-15)+10)}
    function lerp(a,b,t){return a+(b-a)*t}
    function fract(x){return x-Math.floor(x)}
    function hash32(x,y){let h=(x*1973+y*9277)&0x7fffffff;h=(h^(h>>13))*3717791;h=(h^(h>>15))*3593119;return(h^(h>>17))/0x7fffffff}
    function noise2d(x,y,s){s=s||1;const xi=Math.floor(x),yi=Math.floor(y);const fx=fade(fract(x)),fy=fade(fract(y));const h0=hash32(xi,yi)*s,h1=hash32(xi+1,yi)*s,h2=hash32(xi,yi+1)*s,h3=hash32(xi+1,yi+1)*s;const u=lerp(h0,h1,fx),v=lerp(h2,h3,fx);return lerp(u,v,fy)*2-1}
    function fbm(x,y,o,p,l){let t=0,f=1,a=1,m=0;for(let i=0;i<o;i++){t+=noise2d(x*f,y*f)*a;m+=a;a*=p;f*=l}return t/m}
    function lum(r,g,b){return 0.299*r+0.587*g+0.114*b}
    function meanColour(d,w,x0,y0,x1,y1){let r=0,g=0,b=0,c=0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const i=(y*w+x)*4;r+=d[i];g+=d[i+1];b+=d[i+2];c++}return c>0?{r:r/c,g:g/c,b:b/c}:{r:80,g:60,b:40}}

    /**
     * Downscale image to target width, process fractal interpolation at low res,
     * then upscale back to original resolution. This keeps processing under ~200ms
     * even for 4K textures.
     */
    function extrapolateColour(img){
      const ow=img.naturalWidth||img.width,oh=img.naturalHeight||img.height;
      // Downscale to ~480px wide for processing
      const targetW=Math.min(480,ow);
      const targetH=Math.round(oh*(targetW/ow));
      // Draw source to processing canvas
      const pc=document.createElement('canvas');pc.width=targetW;pc.height=targetH;
      const pctx=pc.getContext('2d',{willReadFrequently:true});
      pctx.drawImage(img,0,0,targetW,targetH);
      const id=pctx.getImageData(0,0,targetW,targetH);const d=id.data;
      const w=targetW,h=targetH;
      const sy=Math.floor(h*0.48);
      // Northern palette seed
      const np=meanColour(d,w,0,Math.max(0,sy-Math.floor(h*0.2)),w,sy);
      // Build mask: 1 = empty (below luminance threshold)
      const mask=new Uint8Array(w*h);
      for(let y=sy;y<h;y++)for(let x=0;x<w;x++){if(lum(d[(y*w+x)*4],d[(y*w+x)*4+1],d[(y*w+x)*4+2])<12)mask[y*w+x]=1}
      // O(n) scanline: for each column, find nearest filled pixel above southStartY
      const colSeedR=new Float32Array(w),colSeedG=new Float32Array(w),colSeedB=new Float32Array(w),colSeedY=new Int32Array(w);
      for(let x=0;x<w;x++){
        let found=-1;
        for(let y=sy;y>=0;y--){if(mask[y*w+x]!==1){found=y;break}}
        if(found>=0){const pi=(found*w+x)*4;colSeedR[x]=d[pi];colSeedG[x]=d[pi+1];colSeedB[x]=d[pi+2];colSeedY[x]=found}
        else{colSeedR[x]=np.r;colSeedG[x]=np.g;colSeedB[x]=np.b;colSeedY[x]=0}
      }
      // Fill empty pixels using fractal noise
      for(let y=sy;y<h;y++)for(let x=0;x<w;x++){
        const idx=y*w+x;if(mask[idx]!==1)continue;
        const seedR=colSeedR[x],seedG=colSeedG[x],seedB=colSeedB[x];
        const distToBoundary=y-colSeedY[x];
        const nx=x/(w*1.6),ny=y/(h*1.6);
        const nr=fbm(nx*1.7,ny*1.7,5,0.42,2.3);
        const ng=fbm(nx*2.3+13.1,ny*2.3+7.9,5,0.42,2.3);
        const nb=fbm(nx*3.1+5.3,ny*3.1+11.7,5,0.42,2.3);
        let r=seedR+nr*28,g=seedG+ng*24,b=seedB+nb*20;
        r+=(np.r-128)*0.15;g+=(np.g-128)*0.12;b+=(np.b-128)*0.10;
        if(distToBoundary<Math.floor(h*0.06)){const blend=Math.max(0,Math.min(1,distToBoundary/(h*0.06)));r=lerp(seedR,r,blend);g=lerp(seedG,g,blend);b=lerp(seedB,b,blend)}
        const i=idx*4;
        d[i]=Math.max(0,Math.min(255,Math.round(r)));
        d[i+1]=Math.max(0,Math.min(255,Math.round(g)));
        d[i+2]=Math.max(0,Math.min(255,Math.round(b)))
      }
      pctx.putImageData(id,0,0);
      // Upscale back to original size
      const oc=document.createElement('canvas');oc.width=ow;oc.height=oh;
      const octx=oc.getContext('2d');octx.imageSmoothingEnabled=true;octx.drawImage(pc,0,0,ow,oh);
      return oc
    }

    function extrapolateBump(img){
      const ow=img.naturalWidth||img.width,oh=img.naturalHeight||img.height;
      const targetW=Math.min(480,ow);
      const targetH=Math.round(oh*(targetW/ow));
      const pc=document.createElement('canvas');pc.width=targetW;pc.height=targetH;
      const pctx=pc.getContext('2d',{willReadFrequently:true});pctx.drawImage(img,0,0,targetW,targetH);
      const id=pctx.getImageData(0,0,targetW,targetH);const d=id.data;
      const w=targetW,h=targetH;
      const sy=Math.floor(h*0.48);
      // Northern mean height
      let nm=0,nc=0;for(let y=Math.max(0,sy-Math.floor(h*0.3));y<sy;y++)for(let x=0;x<w;x++){nm+=d[(y*w+x)*4];nc++}nm/=nc;
      const mask=new Uint8Array(w*h);
      for(let y=sy;y<h;y++)for(let x=0;x<w;x++){if(d[(y*w+x)*4]<6)mask[y*w+x]=1}
      const colSeedV=new Float32Array(w),colSeedY=new Int32Array(w);
      for(let x=0;x<w;x++){
        let found=-1;
        for(let y=sy;y>=0;y--){if(mask[y*w+x]!==1){found=y;break}}
        colSeedV[x]=found>=0?d[(found*w+x)*4]:nm;
        colSeedY[x]=found>=0?found:0
      }
      for(let y=sy;y<h;y++)for(let x=0;x<w;x++){
        const idx=y*w+x;if(mask[idx]!==1)continue;
        const seedV=colSeedV[x];
        const distToBoundary=y-colSeedY[x];
        const nx=x/(w*2.0),ny=y/(h*2.0);
        const n=fbm(nx*1.3,ny*1.3,4,0.5,2.1);
        let v=seedV+n*32;
        if(distToBoundary<Math.floor(h*0.05)){const blend=Math.max(0,Math.min(1,distToBoundary/(h*0.05)));v=lerp(seedV,v,blend)}
        v=Math.max(0,Math.min(255,Math.round(v)));
        const i=idx*4;
        d[i]=v;d[i+1]=v;d[i+2]=v
      }
      pctx.putImageData(id,0,0);
      const oc=document.createElement('canvas');oc.width=ow;oc.height=oh;
      const octx=oc.getContext('2d');octx.imageSmoothingEnabled=true;octx.drawImage(pc,0,0,ow,oh);
      return oc
    }

